    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """

    result = dict()
    if len(keys) == 0:
        # no fields were provided, so if is is a Record, return a copy of the Record
        if isinstance(self, Record):
            for k in self.keys:
                result[k] = self[k]

    # there are indexes/keys to extract, so need to extract the fields that
    # were requested
    if len(keys) > 0:
        for key in keys:
            # if it is an integer, extract by index
            if type(key) is int:
                if key < len(self.keys) and key >= 0:
                    result[self.keys[key]] = self[key]
                else:
                    raise IndexError(
                        "key index of " + str(key) + " is out of range")
            # if it is a string, extract named key
            elif type(key) is str:
                if key in self.keys:
                    result[key] = self[key]
                # if it does not exist, need to find the key in self.keys
                else:
                    result[key] = None
            else:
                # just throw an exception, this should not happen
                raise Exception("key must be a string or an integer")

    # return the results
    return result

