def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    def __init__(self, *args):
        if len(args) == len(fields):
            for i, field_name in enumerate(fields):
                setattr(self, field_name, args[i])
        else:
            raise ValueError(f"Expected {len(fields)} arguments, got {len(args)}")

    def __repr__(self):
        field_values = ", ".join([f"{field}={getattr(self, field)!r}" for field in fields])
        return f"{name}({field_values})"

    attrs = {
        '__init__': __init__,
        '__repr__': __repr__,
        '__slots__': tuple(fields)
    }
    if srid_map:
        attrs['srid'] = srid_map

    return type(name, (Point,), attrs)

