def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    import hashlib

    def deterministic_shuffle(lst: list[str]) -> list[str]:
        if len(lst) <= 1:
            return lst

        # Use a hash to create a deterministic permutation
        seed = int(hashlib.sha256(repr(lst).encode()).hexdigest(), 16) % (10 ** 9)
        random_state = list(range(len(lst)))

        # Use a simple deterministic Fisher-Yates shuffle with the seed
        for i in range(len(random_state) - 1, 0, -1):
            j = seed % (i + 1)
            seed = (seed * 31 + 7) % (10 ** 9)
            random_state[i], random_state[j] = random_state[j], random_state[i]

        return [lst[i] for i in random_state]

    return deterministic_shuffle(list(seq))

