def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Create a graph with each element as a node, adding edges as based on incoming and outgoing edges
    # For each ordering, for each pair of adjacent a, b, we add a directed edge.
    # then, we begin traversing
    raw_graph = {}
    # used to count in and outgoing edges
    incoming = {}
    outgoing_edges = {}

    def add_edge(from_node, to_node):
        if from_node not in raw_graph:
            raw_graph[from_node] = set()
        if to_node not in raw_graph:
            raw_graph[to_node] = set()
        if to_node not in raw_graph[from_node]:
            raw_graph[from_node].add(to_node)
        if to_node not in incoming or from_node not in incoming[to_node]:
            incoming[to_node] = incoming.get(to_node, set())
            incoming[to_node].add(from_node)
        if from_node not in outgoing_edges:
            outgoing_edges[from_node] = set()
        if to_node not in outgoing_edges[from_node]:
            outgoing_edges[from_node].add(to_node)

    for ordering in orderings:
        for i in range(len(ordering) - 1):
            add_edge(ordering[i], ordering[i + 1])
    if not orderings:
        return []
    # now we walk the graph
    result = []
    # find nodes that have no in-edges, and add to
    # the result
    zeroed_incoming = [x for x in raw_graph if not len(incoming.get(x, set()))]
    seen = set()

    def add_node(node):
        if node not in seen:
            result.append(node)
            seen.add(node)
            for next_node in outgoing_edges.get(node, set()):
                if next_node in incoming:
                    del incoming[next_node][node]
                if not len(incoming[next_node]):
                    zeroed_incoming.append(next_node)

    while len(zeroed_incoming) and len(seen) < len(raw_graph):
        add_node(zeroed_incoming.pop())
    # make sure to add all
    for key in raw_graph:
        if not (key in seen):
            result.append(key)
    return result

