def _c_optimizations_available(opt_required=False):
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    if opt_required:
        try:
            from .optimizations_c import optimizations_optimized as optimizations
            return optimizations
        except ImportError as err:
            raise ImportError("%s\n\nPlease check that the Cython version and gcc are installed "
                              "and try to reinstall numpy.\n%s" % (err, system_version()))
    else:
        try:
            from .optimizations_c import optimizations_optimized as optimizations
            return optimizations
        except ImportError:
            # Fall back to pure Python
            from . import optimizations
            return optimizations

