def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if isinstance(params, Mapping):
        formatted_params = params
    elif isinstance(params, Sequence):
        formatted_params = params
    else:
        raise TypeError(f"Invalid type for params: {type(params)}")

    if isinstance(self.in_style, tuple):
        name, ordinal = self.in_style
    else:
        name, ordinal = None, None

    if isinstance(params, Mapping):
        if ordinal is not None:
            raise ValueError(f"Ordinal style {ordinal} is not compatible with Mapping params")
        if name is not None:
            formatted_sql = sql
            for param in params:
                if isinstance(param, str):
                    formatted_sql = formatted_sql.replace(name + param, self.out_style)
                elif isinstance(param, int):
                    formatted_sql = formatted_sql.replace(name + str(param), self.out_style)
                else:
                    raise TypeError(f"Invalid type for parameter: {type(param)}")
        else:
            raise ValueError(f"Named style {name} is not defined")
    elif isinstance(params, Sequence):
        if name is not None:
            raise ValueError(f"Named style {name} is not compatible with Sequence params")
        if ordinal is not None:
            formatted_sql = sql
            for idx in range(len(params)):
                formatted_sql = formatted_sql.replace(ordinal + str(idx + 1), self.out_style)
        else:
            raise ValueError(f"Ordinal style {ordinal} is not defined")
    else:
        raise TypeError(f"Invalid type for params: {type(params)}")

    return (formatted_sql, formatted_params)

