        # Validate the inventory based on the determined spec_version
        if spec_version == "1.0":
            self._validate_inventory_v1(inventory)
        elif spec_version == "2.0":
            self._validate_inventory_v2(inventory)
        else:
            raise ValueError(f"Unsupported inventory specification version: {spec_version}")

        return inventory

