def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    result = ""
    current_indent = "  " * indent  # 2 spaces per level of indentation

    # If it's an object with attributes, format them nicely
    if hasattr(self, '__dict__'):
        result += "{} {{\n".format(type(self).__name__)
        for key, value in vars(self).items():
            # Handle nested objects
            if hasattr(value, 'pretty'):
                nested = value.pretty(indent=indent + 1, debug=debug)
                nested_lines = nested.split('\n')
                # Indent the first line appropriately and subsequent lines
                result += "{}{}: {}\n".format("  " * (indent + 1), key, nested_lines[0])
                if len(nested_lines) > 1:
                    for line in nested_lines[1:]:
