def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if indent < 0:
        raise ValueError("indent must be non-negative")

    # Generate a pretty string representation
    def _indent_str(level):
        return " " * level * 2

    def _render(obj, level=0):
        if obj is None:
            return "None"
        elif isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k, v in obj.items():
                key_repr = _render(k, level)
                val_repr = _render(v, level + 1)
                items.append(f"{_indent_str(level + 1)}{key_repr}: {val_repr}")
            return "{\n" + ",\n".join(items) + "\n" + _indent_str(level) + "}"
        elif isinstance(obj, (list, tuple)):
            if not obj:
                return "[]" if isinstance(obj, list) else "()"
            items = []
            for item in obj:
                items.append(_render(item, level + 1))
            sep = ",\n" + _indent_str(level + 1)
            return (
