                + sep.join(items)
                + "\n" + _indent_str(level)
                + ("]" if isinstance(obj, list) else ")")
            )
        elif isinstance(obj, str):
            return repr(obj)
        else:
            # Default to standard repr
            return repr(obj)

    return _render(self, indent)

