def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if style == "pep440-legacy":
        # Returning "all" pieces of the version described by dev releases
        # enables the customization of version generation, e.g.:
        #
        #   1.0.0-2-gabc123d45
        #
        # These can be converted into a PEP440 compliant string via a transform
        # in the version control system:
        #
        #   1.0.0.dev2+abc123d45
        #
        return pieces["nearest-tag"], "-".join(
            (piece for piece in pieces.values() if piece)
        )
    elif style == "pep440" or style == "pep440-not-extended":
        # Note: This is an extension of the PEP440 spec.
        # The version strings described below with a local segment are
        # compliant with PEP440.
        if pieces.get("distance") == 0:
            # This is a "tagged" (i.e. release) version
            if style == "pep440-not-extended":
                return pieces["nearest-tag"]
            else:
                return pieces["nearest-tag"] + "+{}".format(pieces["commit"])
        elif pieces.get("dirty"):
            # The branch is dirty; not PEP440 compliant until the local segment
            # allows a special value of "dirty"
            if style == "pep440-not-extended":
                return "{}.post{}".format(
                    pieces["nearest-tag"], pieces["distance"]
                )
            else:
                return "{}.post{}+{}".format(
                    pieces["nearest-tag"], pieces["distance"], pieces["commit"]
                )
        else:
            # This is a development version between tags
            if style == "pep440-not-extended":
                return "{}.dev{}".format(
                    pieces["nearest-tag"], pieces["distance"]
                )
            else:
                return "{}.dev{}+{}".format(
                    pieces["nearest-tag"], pieces["distance"], pieces["commit"]
                )
    else:
        raise ValueError("Unknown style: {}".format(style))

