def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Check if the path exists
    if not os.path.exists(path):
        return f'error: path does not exist: {path}'

    # Check if the path is a file
    if os.path.isfile(path):
        return 'file'

    # Check if the path is a directory
    if os.path.isdir(path):
        # Look for "0=*" files in the directory
        namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]

        if len(namaste_files) == 0:
            return 'error: not an OCFL directory (no 0=* files found)'

        # If there's exactly one 0=* file, check its name
        if len(namaste_files) == 1:
            namaste_file = namaste_files[0]
            # Parse the version from the namaste file name
            if namaste_file.startswith('0=') and namaste_file[2:].isdigit():
                version = int(namaste_file[2:])
                if version == 0:
                    return 'root'
                else:
                    return 'object'
            else:
                return 'error: malformed 0=* file name'
        else:
            return 'error: multiple 0=* files found'

    return 'error: unknown path type'

