def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    def wildcard_to_regex(wildcard):
        # Escape special regex characters that we don't want to interpret
        # but we keep * as a wildcard
        regex = ''
        for char in wildcard:
            if char == '*':
                regex += '.*'
            elif char in r'\.^$+?{}[]|()/':
                # Escape these characters
                regex += '\\' + char
            else:
                regex += char
        return '^' + regex + '$'

    return {wildcard_to_regex(k): v for k, v in item.items()}

