    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Default to current platform if not specified
    if platform == 'this':
        import sys
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    # Define regex patterns for POSIX and Windows
    # POSIX: handles quotes (single and double), escapes
    pos_pattern = re.compile(r'(?:"((?:\\.|[^"\\])*)"|\'((?:\\.|[^\'\\])*)\'|(\\.|[^\\\s])', re.DOTALL)
    # Windows: handles quotes (double only), backslash escaping, no single quotes
    win_pattern = re.compile(r'(?:"((?:[^"])*?)"|(\S+)', re.DOTALL)

    if platform == 1:
        pattern = pos_pattern
    elif platform == 0:
        pattern = win_pattern
    else:
        raise ValueError("Invalid platform value: %r" % platform)

    tokens = []
    for match in pattern.finditer(s):
        if match.group(1) is not None:
            # Double-quoted string
            tokens.append(match.group(1))
        elif match.group(2) is not None:
            if platform == 1:
                # Single-quoted string
                tokens.append(match.group(2))
            else:
                # Unquoted string (Windows)
                tokens.append(match.group(2))
        elif match.group(3) is not None:
            # Single character (possibly escaped)
            tokens.append(match.group(3))

    return tokens

