def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None
    try:
        number, unit = frequency.split()
    except ValueError:
        raise ValueError('Invalid frequency string: {}'.format(frequency))
    try:
        number = int(number)
    except ValueError:
        raise ValueError('Invalid number in frequency string: {}'.format(frequency))
    if unit not in ['year', 'years', 'month', 'months', 'week', 'weeks', 'day', 'days', 'hour', 'hours', 'minute', 'minutes', 'second', 'seconds']:
        raise ValueError('Invalid unit in frequency string: {}'.format(frequency))
    unit_name = unit[:-1] if unit.endswith('s') else unit
    if unit_name == 'year':
        return datetime.timedelta(weeks=number * 52)
    elif unit_name == 'month':
        return datetime.timedelta(days=number * 30)
    elif unit_name == 'week':
        return datetime.timedelta(weeks=number)
    elif unit_name == 'day':
        return datetime.timedelta(days=number)
    elif unit_name == 'hour':
        return datetime.timedelta(hours=number)
    elif unit_name == 'minute':
        return datetime.timedelta(minutes=number)
    elif unit_name == 'second':
        return datetime.timedelta(seconds=number)

