def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    # Perform a HEAD request and read the content-type header.
    try:
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req) as response:
            content_type = response.headers.get('Content-Type')
            if content_type:
                # Strip parameters like charset
                content_type = content_type.split(';')[0].strip()
            else:
                return None
            return content_type.lower()
    except urllib.error.URLError:
        # If a URL cannot be fetched for whatever reason, we can't determine the content type.
        # For instance, the ION Adaptive Bitrate Switcher WebClient sends out HEAD requests to detect UTF encoding.
        # Some hosts do not support HEAD and simply close the connection. We should continue in such cases.
        return None

