def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    stripped_document = document.strip()
    if stripped_document.startswith("{"):
        try:
            parsed = json.loads(stripped_document)
            # In JSON format, the webfinger properties are directly in the response
            result = {}
            if "links" in parsed:
                for link in parsed["links"]:
                    if link.get("rel") == "lrdd":
                        result["lrdd_url"] = link.get("template")
                    elif link.get("rel") == "http://diaspora protocols/fumble":
                        result["fumble"] = link.get("template")
                    elif link.get("rel") == "http://diaspora protocols/hcard":
                        result["hcard_url"] = link.get("template")
            return result
        except json.JSONDecodeError:
            pass

    if stripped_document.startswith("<"):
        try:
            root = ET.fromstring(stripped_document)
            # XRD format
            result = {}
            # Find all Link elements
            for link in root.findall('.//{urn:xrd:schemas:atom:crossdomain}Link') if root.get('xmlns', '').endswith('crossdomain') or True else []:
                rel = link.get('rel')
                template = link.get('template')
                if rel == "lrdd":
                    result["lrdd_url"] = template
                elif rel == "http://diaspora protocols/fumble":
                    result["fumble"] = template
                elif rel == "http://diaspora protocols/hcard":
                    result["hcard_url"] = template
            return result
        except ET.ParseError:
            pass

    # If neither JSON nor XRD could be parsed, return empty dict
    return {}

